// GENERATED by npm run landing:data from src/widgets/app/graph-view/graph-layout.ts. Do not edit.
/**
 * Layout for the graph-view widget. Pure and deterministic: the same subgraph always gives the
 * same picture. The widget only draws what the tools return; it ranks nothing itself.
 *
 * Layers: importers sit to the left of the files they import. Distance is measured from the
 * highlighted files (one step right for each import, one step left for each importer), so the
 * current stop is in the middle and its callers and callees fan out either side.
 */

export interface SgNode {
  id: string;
  label: string;
  path: string;
  centrality: number;
  highlight: boolean;
  role?: string;
}

export interface SgEdge {
  from: string;
  to: string;
}

export interface PlacedNode {
  node: SgNode;
  x: number;
  y: number;
  w: number;
  h: number;
  layer: number;
}

export interface PlacedEdge {
  from: string;
  to: string;
  /** SVG path data (cubic curve). */
  d: string;
  /** True when it touches a highlighted file. */
  emphasis: boolean;
}

export interface Layout {
  nodes: PlacedNode[];
  edges: PlacedEdge[];
  width: number;
  height: number;
}

export const MAX_NODES = 25;
/** At most this many edges are drawn; the ones touching a highlighted file come first. */
export const MAX_EDGES = 40;
const PAD = 16;
const ROW_H = 36;
const NODE_H = 26;
const COL_GAP = 70;
const MIN_W = 70;
const MAX_W = 190;
const CHAR_W = 6.6;

export function nodeWidth(label: string): number {
  return Math.min(MAX_W, Math.max(MIN_W, Math.round(label.length * CHAR_W + 20)));
}

/** Relative layer of every node: 0 for the leftmost, increasing to the right. */
export function assignLayers(nodes: SgNode[], edges: SgEdge[]): Map<string, number> {
  const ids = new Set(nodes.map((n) => n.id));
  const out = new Map<string, string[]>();
  const inn = new Map<string, string[]>();
  for (const e of edges) {
    if (!ids.has(e.from) || !ids.has(e.to) || e.from === e.to) continue;
    out.set(e.from, [...(out.get(e.from) ?? []), e.to]);
    inn.set(e.to, [...(inn.get(e.to) ?? []), e.from]);
  }
  const rel = new Map<string, number>();
  const seeds = nodes.filter((n) => n.highlight).map((n) => n.id);
  const queue: string[] = seeds.length ? [...seeds] : nodes.length ? [nodes[0].id] : [];
  for (const s of queue) rel.set(s, 0);
  for (let i = 0; i < queue.length; i++) {
    const cur = queue[i];
    const at = rel.get(cur)!;
    for (const next of out.get(cur) ?? []) if (!rel.has(next)) (rel.set(next, at + 1), queue.push(next));
    for (const prev of inn.get(cur) ?? []) if (!rel.has(prev)) (rel.set(prev, at - 1), queue.push(prev));
  }
  for (const n of nodes) if (!rel.has(n.id)) rel.set(n.id, 0);
  const min = Math.min(0, ...rel.values());
  const layers = new Map<string, number>();
  for (const [id, v] of rel) layers.set(id, v - min);
  return layers;
}

export function layoutSubgraph(input: { nodes: SgNode[]; edges: SgEdge[] }, maxLayers = 6): Layout {
  const nodes = input.nodes.slice(0, MAX_NODES);
  if (nodes.length === 0) return { nodes: [], edges: [], width: 2 * PAD + MIN_W, height: 2 * PAD + NODE_H };
  const raw = assignLayers(nodes, input.edges);
  const layers = new Map([...raw].map(([id, l]) => [id, Math.min(l, maxLayers - 1)]));
  const cols = Math.max(...layers.values()) + 1;

  const byLayer: SgNode[][] = Array.from({ length: cols }, () => []);
  for (const n of nodes) byLayer[layers.get(n.id)!].push(n);
  for (const col of byLayer) col.sort((a, b) => Number(b.highlight) - Number(a.highlight) || b.centrality - a.centrality || a.label.localeCompare(b.label) || a.id.localeCompare(b.id));

  const colWidth = byLayer.map((col) => Math.max(MIN_W, ...col.map((n) => nodeWidth(n.label))));
  const colX: number[] = [];
  let x = PAD;
  for (let c = 0; c < cols; c++) {
    colX.push(x);
    x += colWidth[c] + COL_GAP;
  }
  const width = x - COL_GAP + PAD;
  const rows = Math.max(...byLayer.map((c) => c.length));
  const height = 2 * PAD + rows * ROW_H - (ROW_H - NODE_H);

  const placed = new Map<string, PlacedNode>();
  byLayer.forEach((col, c) => {
    const colHeight = col.length * ROW_H - (ROW_H - NODE_H);
    const top = PAD + (height - 2 * PAD - colHeight) / 2; // centre each column vertically
    col.forEach((n, r) => {
      const w = nodeWidth(n.label);
      placed.set(n.id, { node: n, x: colX[c] + (colWidth[c] - w) / 2, y: top + r * ROW_H, w, h: NODE_H, layer: c });
    });
  });

  const seen = new Set<string>();
  const edges: PlacedEdge[] = [];
  for (const e of input.edges) {
    const a = placed.get(e.from);
    const b = placed.get(e.to);
    const key = `${e.from}>${e.to}`;
    if (!a || !b || a === b || seen.has(key)) continue;
    seen.add(key);
    const forward = b.x >= a.x;
    const x1 = forward ? a.x + a.w : a.x;
    const x2 = forward ? b.x : b.x + b.w;
    const y1 = a.y + a.h / 2;
    const y2 = b.y + b.h / 2;
    const dx = Math.max(24, Math.abs(x2 - x1) / 2);
    const sign = forward ? 1 : -1;
    edges.push({ from: e.from, to: e.to, d: `M${x1.toFixed(1)},${y1.toFixed(1)} C${(x1 + sign * dx).toFixed(1)},${y1.toFixed(1)} ${(x2 - sign * dx).toFixed(1)},${y2.toFixed(1)} ${x2.toFixed(1)},${y2.toFixed(1)}`, emphasis: a.node.highlight || b.node.highlight });
  }
  // A dense graph is unreadable: always keep the edges that touch the current stop, then fill up to the cap.
  const kept = [...edges.filter((e) => e.emphasis), ...edges.filter((e) => !e.emphasis)].slice(0, MAX_EDGES);
  return { nodes: [...placed.values()], edges: kept, width, height };
}

/** The subgraph lives at `subgraph` in tour_next and explain_file results; accept a bare subgraph too. */
export function subgraphOf(output: unknown): { nodes: SgNode[]; edges: SgEdge[]; highlight: string[]; note?: string } | null {
  const o = output as { subgraph?: unknown; nodes?: unknown } | null | undefined;
  const sg = (o && typeof o === 'object' && 'subgraph' in o ? o.subgraph : o) as { nodes?: unknown; edges?: unknown; highlight?: unknown; note?: unknown } | undefined;
  if (!sg || !Array.isArray(sg.nodes)) return null;
  const nodes = (sg.nodes as Partial<SgNode>[])
    .filter((n) => typeof n?.id === 'string')
    .slice(0, MAX_NODES)
    .map((n) => ({ id: n.id!, label: String(n.label ?? n.id).slice(0, 60), path: String(n.path ?? n.id), centrality: Number(n.centrality) || 0, highlight: Boolean(n.highlight), role: typeof n.role === 'string' ? n.role : undefined }));
  const edges = (Array.isArray(sg.edges) ? (sg.edges as Partial<SgEdge>[]) : []).filter((e) => typeof e?.from === 'string' && typeof e?.to === 'string').map((e) => ({ from: e.from!, to: e.to! }));
  return { nodes, edges, highlight: Array.isArray(sg.highlight) ? (sg.highlight as unknown[]).filter((h): h is string => typeof h === 'string') : [], note: typeof sg.note === 'string' ? sg.note : undefined };
}
